import { useEffect, useMemo, useState } from 'react';

/**
 * HUD language library (PLAN-110): the motifs, their meaning and where they fit.
 * Reference page for the Director — it reads /assets/ui/hud-real/library/library.json,
 * generated by scripts/hud-real/build-library.py. Proposals, not decisions.
 */

interface Use { slot: string; fit: string; why: string }
interface Item {
  id: string; name: string; motif: string; meaning: string[]; image: string; w: number; h: number; status: string;
  silhouette: { form: string; ratio: string; minPx: number }; uses: Use[]; pairs: string[]; avoid: string; tags: string[];
}

const BACKDROPS = [
  { id: 'mare', label: 'mare', css: 'linear-gradient(160deg, #1675ad, #0d4d78)' },
  { id: 'notte', label: 'notte', css: '#0a1622' },
  { id: 'giungla', label: 'giungla', css: 'linear-gradient(160deg, #2c4a2a, #14260f)' },
] as const;

const FIT_COLOR: Record<string, string> = { ottimo: '#5ec79a', buono: '#e2c46a', possibile: '#9fb8c4' };
const MONO: React.CSSProperties = { fontFamily: 'ui-monospace, monospace', fontSize: 11, letterSpacing: 1 };

export default function HudLibraryPage() {
  const [items, setItems] = useState<Item[]>([]);
  const [note, setNote] = useState('');
  const [bd, setBd] = useState<(typeof BACKDROPS)[number]['id']>('mare');
  const [tag, setTag] = useState<string | null>(null);
  useEffect(() => {
    fetch('/assets/ui/hud-real/library/library.json').then((r) => r.json()).then((d: { items: Item[]; note: string }) => { setItems(d.items); setNote(d.note); }).catch(() => setItems([]));
  }, []);
  const tags = useMemo(() => [...new Set(items.flatMap((i) => i.tags.map((t) => t.split(' ')[0])))].sort(), [items]);
  const shown = items.filter((i) => !tag || i.tags.some((t) => t.startsWith(tag)));
  const css = BACKDROPS.find((b) => b.id === bd)!.css;

  return (
    <div style={{ position: 'fixed', inset: 0, overflow: 'auto', background: '#07131c', color: '#dfe9ee', fontFamily: '"EB Garamond", serif' }}>
      <div style={{ padding: '14px 18px', display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center', position: 'sticky', top: 0, background: 'rgba(7,19,28,0.95)', zIndex: 5 }}>
        <strong style={{ ...MONO, fontSize: 13, color: '#f1dfa8' }}>LIBRERIA DEI MOTIVI · linguaggio HUD</strong>
        {BACKDROPS.map((b) => (
          <button key={b.id} type="button" onClick={() => setBd(b.id)} style={{ ...MONO, color: '#cfe6f0', background: 'rgba(3,14,24,0.85)', border: `1px solid ${bd === b.id ? '#d4af37' : 'transparent'}`, borderRadius: 4, padding: '4px 9px', cursor: 'pointer' }}>{b.label}</button>
        ))}
        <span style={{ ...MONO, color: '#9fb8c4' }}>etichetta:</span>
        {[null, ...tags].map((t) => (
          <button key={t ?? 'tutte'} type="button" onClick={() => setTag(t)} style={{ ...MONO, color: '#cfe6f0', background: 'rgba(3,14,24,0.85)', border: `1px solid ${tag === t ? '#d4af37' : 'transparent'}`, borderRadius: 4, padding: '4px 9px', cursor: 'pointer' }}>{t ?? 'tutte'}</button>
        ))}
      </div>
      <p style={{ margin: '0 18px 8px', fontSize: 13, color: '#9fb8c4', maxWidth: 900 }}>{note}</p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(420px, 1fr))', gap: 14, padding: '8px 18px 28px' }}>
        {shown.map((it) => (
          <section key={it.id} data-motif={it.id} style={{ display: 'flex', gap: 14, background: 'rgba(10,30,42,0.85)', border: '1px solid rgba(160,200,220,0.15)', borderRadius: 8, padding: 12 }}>
            <div style={{ flex: 'none', width: 200, minHeight: 250, background: css, borderRadius: 6, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <img src={it.image} alt={it.name} draggable={false} style={{ maxWidth: 190, maxHeight: 240, objectFit: 'contain' }} />
            </div>
            <div style={{ fontSize: 14, lineHeight: 1.4, minWidth: 0 }}>
              <div style={{ ...MONO, color: '#9fb8c4' }}>{it.id} · {it.motif}</div>
              <h3 style={{ margin: '2px 0 4px', color: '#f1dfa8', fontFamily: 'var(--font-header, "Cinzel", serif)', fontSize: 18 }}>{it.name}</h3>
              <div><span style={{ color: '#9fb8c4' }}>Significa:</span> {it.meaning.join(' · ')}</div>
              <div><span style={{ color: '#9fb8c4' }}>Forma:</span> {it.silhouette.form}, {it.silhouette.ratio}, minimo {it.silhouette.minPx} px</div>
              <div style={{ margin: '6px 0 2px', color: '#9fb8c4' }}>Dove può stare</div>
              <ul style={{ margin: 0, paddingLeft: 16 }}>
                {it.uses.map((u) => (
                  <li key={u.slot}><span style={{ color: FIT_COLOR[u.fit] ?? '#fff' }}>{u.fit}</span> · <strong>{u.slot}</strong> — {u.why}</li>
                ))}
              </ul>
              <div style={{ marginTop: 6 }}><span style={{ color: '#9fb8c4' }}>Con:</span> {it.pairs.length ? it.pairs.join(', ') : '—'} · <span style={{ color: '#9fb8c4' }}>Evitare:</span> {it.avoid}</div>
              <div style={{ ...MONO, color: '#9fb8c4', marginTop: 6 }}>{it.tags.join(' · ')} · {it.status}</div>
            </div>
          </section>
        ))}
      </div>
    </div>
  );
}
